    /**
     * Tests creating a new Exception_.
     *
     * @return    Exception_
     */
    public Exception_ testCreate() throws Throwable {
    Exception_ entity = null;

    LOGGER.info( "Exception_Test:testCreate()" );
    LOGGER.info( "-- Attempting to create a Exception_");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Exception_" );

    try {
        entity = service.createException_( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getException_Id();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Exception_ with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

