    /**
     * Tests getting all Exception_s.
     *
     * @return    Collection
     */
    public List<Exception_> testGetAll() throws Throwable {
    LOGGER.info( "Exception_Test:testGetAll() - Retrieving Collection of Exception_s:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Exception_ : " );
    List<Exception_> collection  = null;

    try {
        // call the static get method on the Exception_Service
        collection = service.getAllException_();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Exception_ currEntity  = null;
            Iterator<Exception_> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getException_Id(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

